<?php

namespace Tests\Unit\Kri;

use App\Support\Kri\KriBandRule;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\Attributes\Test;
use Symfony\Component\Process\Process;
use Tests\TestCase;

/**
 * ADR 0026 section 6.1: the ONE server entry point for "which band is this
 * value in", pinned to the shared truth table.
 *
 * resources/js/lib/kri-band-truth-table.json holds (direction, green, red,
 * value) -> band cases worked by hand from MeasureThreshold::bandFor(), NOT
 * generated by running either implementation. This file runs every case
 * through KriBandRule; tools/kri-band-check.mjs runs the same cases through the
 * browser mirror, and the last test here executes it.
 *
 * THE EDGES, FROZEN: a value exactly on the RED boundary is red in BOTH
 * directions; a value exactly on the GREEN boundary is amber in BOTH.
 */
class KriBandRuleTest extends TestCase
{
    private const TABLE = 'resources/js/lib/kri-band-truth-table.json';

    /** @return array<string, mixed> */
    private static function table(): array
    {
        // base_path() is not available in a data provider (the app is not booted).
        $path = dirname(__DIR__, 3).'/'.self::TABLE;

        return json_decode((string) file_get_contents($path), true, 512, JSON_THROW_ON_ERROR);
    }

    /** @return array<string, array{0: string, 1: mixed, 2: mixed, 3: mixed, 4: ?string}> */
    public static function cases(): array
    {
        $out = [];

        foreach (self::table()['cases'] as $case) {
            $out[$case['id']] = [$case['direction'], $case['green'], $case['red'], $case['value'], $case['band']];
        }

        return $out;
    }

    #[Test]
    #[DataProvider('cases')]
    public function the_server_rule_agrees_with_the_truth_table(string $direction, mixed $green, mixed $red, mixed $value, ?string $expected): void
    {
        $bands = app(KriBandRule::class);

        $rule = $bands->forBoundaries($direction, $green, $red);
        $got = $bands->bandOf($rule, $value === null ? null : (float) $value);

        $this->assertSame($expected, $got, "{$direction} green={$green} red={$red} value={$value}");
    }

    #[Test]
    public function the_table_pins_the_frozen_edges_for_both_directions(): void
    {
        $byId = [];

        foreach (self::table()['cases'] as $case) {
            $byId[$case['id']] = $case;
        }

        // Guard the guard: a table that lost these rows would pass vacuously.
        $this->assertSame('red', $byId['hw-on-red-boundary-is-red']['band'] ?? null);
        $this->assertSame('red', $byId['lw-on-red-boundary-is-red']['band'] ?? null);
        $this->assertSame('amber', $byId['hw-on-green-boundary-is-amber']['band'] ?? null);
        $this->assertSame('amber', $byId['lw-on-green-boundary-is-amber']['band'] ?? null);

        // And both directions, a null green, a null red, both null, and inverted boundaries are present.
        $directions = array_unique(array_column(self::table()['cases'], 'direction'));
        $this->assertContains('higher_is_worse', $directions);
        $this->assertContains('lower_is_worse', $directions);
        $this->assertNotEmpty(array_filter(self::table()['cases'], fn ($c) => $c['green'] === null && $c['red'] !== null));
        $this->assertNotEmpty(array_filter(self::table()['cases'], fn ($c) => $c['red'] === null && $c['green'] !== null));
        $this->assertNotEmpty(array_filter(self::table()['cases'], fn ($c) => $c['red'] === null && $c['green'] === null));
        $this->assertNotEmpty(array_filter(self::table()['cases'], fn ($c) => str_contains($c['id'], 'inverted')));
    }

    #[Test]
    public function a_null_value_is_no_band_never_green(): void
    {
        $bands = app(KriBandRule::class);
        $rule = $bands->forBoundaries('higher_is_worse', 5, 10);

        $this->assertNull($bands->bandOf($rule, null));
        $this->assertFalse($bands->isRed($rule, null));
    }

    #[Test]
    public function is_red_is_exactly_the_red_band(): void
    {
        $bands = app(KriBandRule::class);

        $higher = $bands->forBoundaries('higher_is_worse', 5, 10);
        $this->assertTrue($bands->isRed($higher, 10.0), 'on the red boundary, higher is worse');
        $this->assertFalse($bands->isRed($higher, 9.99));
        $this->assertFalse($bands->isRed($higher, 5.0), 'on the green boundary is amber, not red');

        $lower = $bands->forBoundaries('lower_is_worse', 10, 5);
        $this->assertTrue($bands->isRed($lower, 5.0), 'on the red boundary, lower is worse');
        $this->assertFalse($bands->isRed($lower, 5.01));
        $this->assertFalse($bands->isRed($lower, 10.0), 'on the green boundary is amber, not red');
    }

    #[Test]
    public function every_read_rule_uses_the_engine_spelling_whichever_spelling_came_in(): void
    {
        // A1.7: the form spells it higher_is_worse; every read prop spells it higher_worse.
        $bands = app(KriBandRule::class);

        $this->assertSame('higher_worse', $bands->forBoundaries('higher_is_worse', 5, 10)['direction']);
        $this->assertSame('higher_worse', $bands->forBoundaries('higher_worse', 5, 10)['direction']);
        $this->assertSame('lower_worse', $bands->forBoundaries('lower_is_worse', 10, 5)['direction']);
        $this->assertSame('lower_worse', $bands->forBoundaries('lower_worse', 10, 5)['direction']);
    }

    #[Test]
    public function the_bands_are_in_the_order_the_engine_iterates(): void
    {
        $bands = app(KriBandRule::class);

        $this->assertSame(['green', 'amber', 'red'], array_column($bands->forBoundaries('higher_is_worse', 5, 10)['bands'], 'code'));
        $this->assertSame(['red', 'amber', 'green'], array_column($bands->forBoundaries('lower_is_worse', 10, 5)['bands'], 'code'));
    }

    #[Test]
    public function no_boundaries_is_no_rule(): void
    {
        $rule = app(KriBandRule::class)->forBoundaries('higher_is_worse', null, null);

        $this->assertSame([], $rule['bands']);
    }

    #[Test]
    public function the_browser_mirror_agrees_with_the_same_table(): void
    {
        // There is no JavaScript test runner here, so the mirror is exercised
        // under node, as RcsaCalculationTest does for the RCSA calculator.
        // Skips rather than fails when node is absent: when it skips, the mirror
        // is UNVERIFIED, and a green suite on such an image is no evidence the
        // two agree.
        $node = trim((string) shell_exec('command -v node 2>/dev/null'));

        if ($node === '') {
            $this->markTestSkipped('node is not available, so the browser mirror cannot be exercised.');
        }

        $process = new Process([$node, base_path('tools/kri-band-check.mjs')], base_path(), null, null, 60);
        $process->run();

        $this->assertSame(
            0,
            $process->getExitCode(),
            'resources/js/lib/kri-band.js disagrees with the truth table: '.$process->getErrorOutput().$process->getOutput()
        );
        $this->assertStringContainsString((string) count(self::table()['cases']).'/'.count(self::table()['cases']).' cases agree', $process->getOutput());
    }
}
